window.__votdWeek && window.__votdWeek({"week":"2029-08-06","reading":"Doctrine and Covenants 85–87","days":[{"d":"2029-08-06","ref":"D&C 85:6","b":"D&C","c":85,"v":6,"he":"אָכֵן כֹּה אָמַר קוֹל דְּמָמָה דַקָּה הַלּוֹחֵשׁ וְחֹדֵר בְּכׇל דָּבָר וְלִפְעָמִים הוּא מַרְעִיד אֶת־עַצְמוֹתַי בְּהִתְגַּלּוֹתוֹ לֵאמֹר׃","en":"Yea, thus saith the still small voice, which whispereth through and pierceth all things, and often times it maketh my bones to quake while it maketh manifest, saying:"},{"d":"2029-08-07","ref":"D&C 85:8","b":"D&C","c":85,"v":8,"he":"וְאוֹתוֹ אִישׁ אֲשֶׁר נִקְרָא מֵאֵת אֱלֹהִים וְהׇפְקַד הַשֹּׁלֵחַ יָדוֹ לִתְמֹךְ בַּאֲרוֹן הָאֱלֹהִים יִפֹּל בְּחֵץ הַמָּוֶת כְּעֵץ הַמֻּכֶּה בְּחֵץ הַבָּרָק הַלּוֹהֵט׃","en":"While that man, who was called of God and appointed, that putteth forth his hand to steady the ark of God, shall fall by the shaft of death, like as a tree that is smitten by the vivid shaft of lightning."},{"d":"2029-08-08","ref":"D&C 85:9","b":"D&C","c":85,"v":9,"he":"וְכׇל אֲשֶׁר לֹא נִמְצָאִים כְּתוּבִים בְּסֵפֶר הַזִּכָּרוֹן לֹא יִמְצְאוּ נַחֲלָה בַּיּוֹם הַהוּא כִּי־אִם יִכָּרְתוּ וְחֶלְקָם יוּשַׂם לָהֶם בֵּין אֲשֶׁר לֹא־אֵמֻן בָּם אֲשֶׁר שָׁם מִסְפֵּד וַחֲרֹק שִׁנָּיִם׃","en":"And all they who are not found written in the book of remembrance shall find none inheritance in that day, but they shall be cut asunder, and their portion shall be appointed them among unbelievers, where are wailing and gnashing of teeth."},{"d":"2029-08-09","ref":"D&C 86:11","b":"D&C","c":86,"v":11,"he":"לָכֵן בְּרוּכִים אַתֶּם אִם תַּעַמְדוּ בְּטוּבִי אוֹר לַגּוֹיִם וְדֶרֶךְ הַכְּהֻנָּה הַזֹּאת מוֹשִׁיעַ לְעַמִּי יִשְׂרָאֵל יְהוָה אָמַר אָמֵן׃","en":"Therefore, blessed are ye if ye continue in my goodness, a light unto the Gentiles, and through this priesthood, a savior unto my people Israel. The Lord hath said it. Amen."},{"d":"2029-08-10","ref":"D&C 87:5","b":"D&C","c":87,"v":5,"he":"וְהָיָה גַּם הַשְּׁאֵרִית הַנִּשְׁאָרִים בָּאָרֶץ יֵאָסְפוּ וְחָרָה אַפָּם מְאֹד וְהֵצֵרוּ לַגּוֹיִם צָרָה קָשָׁה׃","en":"And it shall come to pass also that the remnants who are left of the land will marshal themselves, and shall become exceedingly angry, and shall vex the Gentiles with a sore vexation."},{"d":"2029-08-11","ref":"D&C 87:7","b":"D&C","c":87,"v":7,"he":"לְמַעַן זַעֲקַת הַקְּדוֹשִׁים וּדְמֵי הַקְּדוֹשִׁים תֶּחְדַּל לַעֲלוֹת לְאׇזְנֵי יְהוָה צְבָאוֹת מִן הָאָרֶץ לְהִנָּקֵם מֵאוֹיְבֵיהֶם׃","en":"That the cry of the saints, and of the blood of the saints, shall cease to come up into the ears of the Lord of Sabaoth, from the earth, to be avenged of their enemies."},{"d":"2029-08-12","ref":"D&C 87:8","b":"D&C","c":87,"v":8,"he":"לָכֵן עִמְדוּ בִּמְקוֹמוֹת קְדוֹשִׁים וְאַל תִּמּוֹטוּ עַד בּוֹא יוֹם יְהוָה כִּי הִנֵּה מְהֵרָה יָבוֹא נְאֻם יְהוָה אָמֵן׃","en":"Wherefore, stand ye in holy places, and be not moved, until the day of the Lord come; for behold, it cometh quickly, saith the Lord. Amen."}]});
